--
-- Table structure for table `course_curriculum_subjects`
--

DROP TABLE IF EXISTS `course_curriculum_subjects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `course_curriculum_subjects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `course_curriculum_id` bigint(20) unsigned NOT NULL,
  `subject_id` bigint(20) unsigned NOT NULL,
  `year_block_id` bigint(20) unsigned NOT NULL,
  `semester_id` bigint(20) unsigned NOT NULL,
  `credited_units` decimal(5,2) NOT NULL DEFAULT 0.00,
  `display_order` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cc_subjects_unique_row` (`course_curriculum_id`,`subject_id`,`year_block_id`,`semester_id`),
  KEY `cc_subjects_subject_fk` (`subject_id`),
  KEY `cc_subjects_year_block_fk` (`year_block_id`),
  KEY `cc_subjects_semester_fk` (`semester_id`),
  KEY `cc_subjects_curriculum_year_sem_order_idx` (`course_curriculum_id`,`year_block_id`,`semester_id`,`display_order`),
  KEY `cc_subjects_curriculum_display_idx` (`course_curriculum_id`,`display_order`,`id`),
  CONSTRAINT `cc_subjects_curriculum_fk` FOREIGN KEY (`course_curriculum_id`) REFERENCES `course_curricula` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cc_subjects_semester_fk` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`),
  CONSTRAINT `cc_subjects_subject_fk` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cc_subjects_year_block_fk` FOREIGN KEY (`year_block_id`) REFERENCES `year_blocks` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12018 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
