--
-- Table structure for table `courses`
--

DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `program_type` varchar(255) DEFAULT NULL,
  `college_id` bigint(20) unsigned DEFAULT NULL,
  `department_id` bigint(20) unsigned NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `total_units` decimal(7,2) DEFAULT NULL,
  `academic_year` varchar(20) DEFAULT NULL,
  `slots` int(10) unsigned NOT NULL DEFAULT 0,
  `track_category` varchar(255) DEFAULT NULL,
  `non_filipino` tinyint(1) NOT NULL DEFAULT 0,
  `dean_director_id` bigint(20) unsigned DEFAULT NULL,
  `program_file` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courses_code_unique` (`code`),
  KEY `courses_department_id_foreign` (`department_id`),
  KEY `courses_dean_director_id_foreign` (`dean_director_id`),
  KEY `courses_college_id_idx` (`college_id`),
  CONSTRAINT `courses_college_id_foreign` FOREIGN KEY (`college_id`) REFERENCES `colleges` (`id`) ON DELETE SET NULL,
  CONSTRAINT `courses_dean_director_id_foreign` FOREIGN KEY (`dean_director_id`) REFERENCES `faculties` (`id`) ON DELETE SET NULL,
  CONSTRAINT `courses_department_id_foreign` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1029 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

