DROP TABLE IF EXISTS `cross_enrollment_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cross_enrollment_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `academic_term_id` bigint(20) unsigned DEFAULT NULL,
  `course_id` bigint(20) unsigned DEFAULT NULL,
  `year_block_id` bigint(20) unsigned DEFAULT NULL,
  `section` varchar(255) DEFAULT NULL,
  `status_id` bigint(20) unsigned DEFAULT NULL,
  `requested_by` varchar(255) DEFAULT NULL,
  `approved_by` varchar(255) DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `cross_enrollment_requests_student_id_foreign` (`student_id`),
  KEY `cross_enrollment_requests_academic_term_id_idx` (`academic_term_id`),
  KEY `cross_enrollment_requests_status_id_idx` (`status_id`),
  KEY `cross_enrollment_requests_course_id_idx` (`course_id`),
  KEY `cross_enrollment_requests_year_block_id_idx` (`year_block_id`),
  CONSTRAINT `cross_enrollment_requests_academic_term_id_foreign` FOREIGN KEY (`academic_term_id`) REFERENCES `academic_terms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `cross_enrollment_requests_course_id_foreign` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `cross_enrollment_requests_status_id_foreign` FOREIGN KEY (`status_id`) REFERENCES `cross_enrollment_statuses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `cross_enrollment_requests_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cross_enrollment_requests_year_block_id_foreign` FOREIGN KEY (`year_block_id`) REFERENCES `year_blocks` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
